import networkx as nx
from z3 import *

def max_edges_girth(n, g):
    # We want to find the max edges for n=14, girth >= 8
    # Let's just use a SAT solver to find if 29 edges is possible.

    solver = Solver()
    edges = {}
    for i in range(n):
        for j in range(i+1, n):
            edges[(i,j)] = Bool(f"e_{i}_{j}")

    # At least 29 edges
    solver.add(Sum([If(edges[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]) >= 29)

    # Girth >= 8 means no cycles of length 3, 4, 5, 6, 7
    import itertools

    def add_no_cycle(length):
        for cycle in itertools.combinations(range(n), length):
            for p in itertools.permutations(cycle):
                # To avoid duplicates, fix the first element to be the minimum, and the second element < last element
                if p[0] == min(p) and p[1] < p[-1]:
                    cycle_edges = []
                    for k in range(length):
                        u, v = p[k], p[(k+1)%length]
                        if u > v: u, v = v, u
                        cycle_edges.append(edges[(u,v)])
                    solver.add(Or([Not(e) for e in cycle_edges]))

    for l in range(3, 8):
        add_no_cycle(l)

    print("Checking...")
    res = solver.check()
    if res == sat:
        print("SAT")
        m = solver.model()
        ans = [(i,j) for i in range(n) for j in range(i+1, n) if is_true(m[edges[(i,j)]])]
        print(ans)
    else:
        print("UNSAT")

max_edges_girth(14, 8)

