    # Maximize edges
    edge_vars = [If(edges[(i,j)], 1, 0) for i in range(n) for j in range(i+1, n)]

    import itertools

    def add_no_cycle(length):
        for cycle in itertools.combinations(range(n), length):
            for p in itertools.permutations(cycle):
                if p[0] == min(p) and p[1] < p[-1]:
                    cycle_edges = []
                    for k in range(length):
                        u, v = p[k], p[(k+1)%length]
                        if u > v: u, v = v, u
                        cycle_edges.append(edges[(u,v)])
                    solver.add(Or([Not(e) for e in cycle_edges]))

    for l in range(3, 8):
        add_no_cycle(l)

    # Check if 15 edges is possible
    solver.add(Sum(edge_vars) >= 15)
    print("Checking 15...")
    if solver.check() == sat:
        print("15 is SAT")
    else:
